package com.codeguardian.controller; import com.codeguardian.dto.*; import com.codeguardian.entity.Role; import com.codeguardian.service.RoleService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.*; import java.util.List; @Controller @RequestMapping("/admin/roles") @RequiredArgsConstructor public class RoleController{private final RoleService service; @GetMapping public String page(){return "admin/roles";} @GetMapping("/api") @ResponseBody public List<Role> all(){return service.getAllRoles();} @GetMapping("/api/with-permissions") @ResponseBody public List<RoleDTO> allDto(){return service.getAllRolesWithPermissions();} @GetMapping("/api/{id}") @ResponseBody public RoleDTO one(@PathVariable Long id){return service.getRoleById(id);} @PostMapping("/api") @ResponseBody public RoleDTO create(@Valid @RequestBody RoleCreateDTO d){return service.createRole(d);} @PutMapping("/api/{id}") @ResponseBody public RoleDTO update(@PathVariable Long id,@Valid @RequestBody RoleUpdateDTO d){return service.updateRole(id,d);} @DeleteMapping("/api/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){service.deleteRole(id);return ResponseEntity.ok().build();} @PostMapping("/api/{id}/permissions") public ResponseEntity<Void> perms(@PathVariable Long id,@RequestBody List<String> c){service.assignPermissions(id,c);return ResponseEntity.ok().build();}}
